def readiness_missing_sections(violations: list[dict[str, str]]) -> list[str]:
    return sorted({
        item["detail"] for item in violations
        if item["code"] in {
            "frontmatter_missing",
            "artifact_missing",
            "placeholder_only_section",
            "heading_missing",
        }
