      "const": "active"
     }
    }
   },
   "then": {
    "properties": {
     "confirmation_status": {
      "const": "confirmed"
     },
     "evaluation_status": {
      "const": "pass"
     },
     "implementation_readiness": {
      "properties": {
       "status": {
        "const": "complete"
       }
      }
     }
    }
   }
  },
