         "const": true
        }
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "tracker_binding": {
      "const": "github"
     },
     "completion_evidence": {
      "properties": {
       "status": {
        "const": "done"
       },
       "policy": {
        "const": "linked_pr_merged_any"
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "pull_request_linkages": {
      "contains": {
       "properties": {
        "closing_reference_verified": {
         "const": true
        }
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "tracker_binding": {
      "const": "none"
     }
    }
   },
   "then": {
    "properties": {
     "beads_linkage": {
      "const": null
     },
     "github_publication": {
      "properties": {
       "mode": {
        "const": "local_only"
       }
      }
     }
    }
   }
  }
 ]
}

